contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint amount) public payable {
        require(true, "");
        // Create a fresh proposal so we have a known, valid proposal ID
        c.newGrantProposal(recipient, amount);
        uint pid = c.proposalCount();

        bool majority = c.hasMajority(pid);
        bool quorum = c.hasQuorum(pid);
        bool minority = c.hasMinority(pid);

        // Threshold ordering: majority (> totalWeight/2) implies quorum (> totalWeight/3),
        // and quorum implies minority (> totalWeight/6).
        assert(!majority || (quorum && minority));
    }

    receive() external payable {}
}

